<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import PersonName from './PersonName.vue'
import UserSelect from './UserSelect'
import QualityIssuePanel from './QualityIssuePanel.vue'
import { createClientUuid } from '../clientId'
import { assignQualityAdoption, deleteQualityTheme, publishQualityExperience, qualityClosed, qualityDate, qualityEventLabel, qualityFailure, qualityName, readQualityReview, saveQualityImprovement, saveQualityObservation, saveQualitySettings, saveQualityTheme, transitionImprovement } from '../qualityReview'
import type { QualityExperience, QualityImprovement, QualityIssueRow, QualityTheme, QualityWorkspace, SaveImprovement } from '../qualityReview'
import '../styles/quality-review.css'

const props=defineProps<{token:string;companyId?:string;projectId?:string;themesOnly?:boolean;showCompanyReviewEntry?:boolean;companyReviewRevision?:number}>()
const emit=defineEmits<{updated:[];openIssue:[projectId:string,issueId:string];openCompanyReview:[]}>()
const data=ref<QualityWorkspace>(),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),tab=ref(props.themesOnly?'themes':'issues')
const query=ref(''),projectFilter=ref(''),domainFilter=ref(''),themeFilter=ref(''),stateFilter=ref(''),selectedId=ref('')
const dialog=ref(''),editingId=ref(''),focusedIssue=ref<QualityIssueRow>(),dialogError=ref('')
const themeDraft=ref({name:'',description:'',isActive:true})
const blankImprovement=():SaveImprovement=>({expectedRowVersion:0,themeId:'',title:'',owner:'',rootCause:'',goal:'',dueOn:'',minimumSamples:3,observationDays:30,maximumFailures:0,actions:[]})
const improvementDraft=ref(blankImprovement())
const observationDraft=ref({projectId:'',appliedOn:'',observedOn:'',passed:true,evidence:''})
const experienceDraft=ref({improvementId:'',title:'',content:'',applicability:''}), experienceTags=ref('')
const adoptionDraft=ref({experienceId:'',projectIds:[] as string[],owner:'',dueOn:''})
const settingsDraft=ref({windowDays:90,eventThreshold:3,projectThreshold:2})
let generation=0,editVersion=0
const caps=computed(()=>data.value?.capabilities??{})
const showIssueFilters = computed(() => tab.value === 'issues' && caps.value.canViewDetails === true)
const people=computed(()=>data.value?.people??[])
const selected=computed(()=>data.value?.catalog.improvements.find(item=>item.id===selectedId.value))
const editingImprovement=computed(()=>data.value?.catalog.improvements.find(item=>item.id===editingId.value))
const canEditDefinition=computed(()=>caps.value.canManageImprovements===true&&(!editingImprovement.value||editingImprovement.value.state==='草稿'))
const issues=computed(()=>data.value?.issues.filter(row=>{
  const projectId=props.projectId||projectFilter.value
  return (!projectId||row.issue.projectId===projectId||row.issue.relatedProjectId===projectId||row.rootProjectId===projectId)&&(!domainFilter.value||(domainFilter.value==='未分类'?!row.profile?.domain:row.profile?.domain===domainFilter.value))&&(!themeFilter.value||(themeFilter.value==='__unassigned'?!row.profile?.themeId:row.profile?.themeId===themeFilter.value))&&(!stateFilter.value||(stateFilter.value==='未完成'?!qualityClosed(row.issue.status):row.issue.status===stateFilter.value))&&(!query.value.trim()||`${row.projectCode} ${row.issue.number} ${row.issue.description} ${row.profile?.category??''}`.toLowerCase().includes(query.value.trim().toLowerCase()))
})??[])
const displayedImprovements=computed(()=>data.value?.catalog.improvements.filter(item=>!themeFilter.value||item.themeId===themeFilter.value)??[])
const candidates=computed(()=>data.value?.metrics.filter(item=>item.isCandidate)??[])
const pendingImprovements=computed(()=>data.value?.catalog.improvements.filter(item=>!qualityClosed(item.state))??[])
const dialogTitle=computed(()=>({theme:'共性问题主题',improvement:editingImprovement.value?'改善事项':'新建改善事项',observation:'记录效果观察',experience:'发布经验',adoption:'安排项目采用',issue:'问题闭环资料'}[dialog.value]??''))
const themeName=(id:string)=>data.value?.catalog.themes.find(item=>item.id===id)?.name||'未归类'
const projectName=(id:string)=>data.value?.projects.find(item=>item.id===id)?.code||'项目资料不可见'
async function load(){const run=++generation;loading.value=true;error.value='';try{const result=await readQualityReview(props.token);if(run!==generation)return;data.value=result;settingsDraft.value={...result.catalog.settings};if(!result.catalog.improvements.some(item=>item.id===selectedId.value))selectedId.value=result.catalog.improvements[0]?.id??'';if(!result.capabilities.canViewDetails&&tab.value==='issues')tab.value='themes'}catch(reason){if(run===generation){data.value=undefined;error.value=qualityFailure(reason,'公司问题与改善读取失败，请核对当前公司权限后重试。')}}finally{if(run===generation)loading.value=false}}
watch(()=>[props.token,props.companyId],()=>{data.value=undefined;dialog.value='';selectedId.value='';message.value='';query.value='';projectFilter.value='';themeFilter.value='';void load()},{immediate:true})
onBeforeUnmount(()=>generation++)
watch(()=>props.companyReviewRevision,()=>{void load()})
async function perform(action:()=>Promise<unknown>,success:string,close=true){if(busy.value)return;const run=generation;busy.value=true;error.value='';dialogError.value='';try{await action();if(run!==generation)return;if(close)dialog.value='';message.value=success;emit('updated');await load()}catch(reason){if(run===generation){const text=qualityFailure(reason);if(dialog.value)dialogError.value=text;else error.value=text}}finally{busy.value=false}}
function open(kind:string,id=createClientUuid()){dialog.value=kind;editingId.value=id;dialogError.value='';editVersion=data.value!.catalog.rowVersion}
function editTheme(item?:QualityTheme){open('theme',item?.id);themeDraft.value={name:item?.name??'',description:item?.description??'',isActive:item?.isActive??true}}
async function saveTheme(){if(!themeDraft.value.name.trim()){dialogError.value='请填写主题名称。';return}await perform(()=>saveQualityTheme(editingId.value,{...themeDraft.value,expectedRowVersion:editVersion},props.token),'共性问题主题已保存。')}
async function removeTheme(id:string,name:string){
  if(!caps.value.canManageThemes||!data.value||busy.value)return
  const run=generation,version=data.value.catalog.rowVersion,token=props.token
  try{await ElMessageBox.confirm(`确认删除共性主题“${name}”吗？仅未被业务或历史记录引用的主题可以删除；已有引用请在“维护”中停用。`,'删除共性主题',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'})}catch{return}
  if(run!==generation||!caps.value.canManageThemes||busy.value)return
  await perform(async()=>{await deleteQualityTheme(id,version,token);if(run===generation&&themeFilter.value===id)themeFilter.value=''},'共性问题主题已删除。')
}
function editImprovement(item?:QualityImprovement,themeId=''){open('improvement',item?.id);improvementDraft.value=item?{expectedRowVersion:editVersion,themeId:item.themeId,title:item.title,owner:item.owner,rootCause:item.rootCause,goal:item.goal,dueOn:item.dueOn,minimumSamples:item.minimumSamples,observationDays:item.observationDays,maximumFailures:item.maximumFailures,actions:item.actions.map(action=>({...action}))}:{...blankImprovement(),expectedRowVersion:editVersion,themeId,title:themeId?`${themeName(themeId)}改善`:''}}
function newFromTheme(themeId:string){const active=data.value?.metrics.find(item=>item.themeId===themeId)?.activeImprovementId;if(active){selectedId.value=active;tab.value='improvements';return}editImprovement(undefined,themeId)}
function addAction(){improvementDraft.value.actions.push({id:createClientUuid(),title:'',owner:improvementDraft.value.owner,dueOn:improvementDraft.value.dueOn,completed:false,evidence:''})}
async function saveImprovement(){const item=improvementDraft.value;if(!item.title.trim()||!item.themeId||!item.owner||!item.dueOn){dialogError.value='请填写主题、标题、负责人和完成日期。';return}if(item.actions.some(action=>!action.title.trim()||!action.owner||!action.dueOn||action.completed&&!action.evidence.trim())){dialogError.value='请补充每项措施的内容、负责人、日期；已完成措施必须填写实施证据。';return}const id=editingId.value;await perform(()=>saveQualityImprovement(id,item,props.token),'改善事项已保存。');selectedId.value=id;tab.value='improvements'}
async function transition(action:string,label:string){if(!selected.value||!data.value)return;let note='';try{const result=await ElMessageBox.prompt(`请填写${label}意见。`,label,{confirmButtonText:'确认',cancelButtonText:'取消',inputType:'textarea',inputValidator:value=>value.trim().length>0||'请填写处理意见。'});note=result.value}catch{return}const id=selected.value.id,version=data.value.catalog.rowVersion;await perform(()=>transitionImprovement(id,version,action,note,props.token),`${label}已完成。`)}
function openObservation(){if(!selected.value)return;open('observation',selected.value.id);observationDraft.value={projectId:'',appliedOn:'',observedOn:'',passed:true,evidence:''}}
async function saveObservation(){const item=observationDraft.value;if(!item.projectId||!item.appliedOn||!item.observedOn||!item.evidence.trim()){dialogError.value='请填写样本项目、实施日期、观察日期和结果依据。';return}await perform(()=>saveQualityObservation(editingId.value,{...item,expectedRowVersion:editVersion},props.token),'效果观察记录已保存。')}
function openExperience(item?:QualityExperience){open('experience');experienceTags.value=item?.projectTags?.join('、')??'';experienceDraft.value={improvementId:item?.improvementId??selected.value?.id??'',title:item?.title??selected.value?.title??'',content:item?.content??'',applicability:item?.applicability??''}}
async function saveExperience(){if(!experienceDraft.value.improvementId||!experienceDraft.value.title.trim()||!experienceDraft.value.content.trim()||!experienceDraft.value.applicability.trim()){dialogError.value='请填写来源改善、经验标题、内容和适用范围。';return}await perform(()=>publishQualityExperience(editingId.value,{...experienceDraft.value,projectTags:experienceTags.value.split(/[,，、;；]/).map(tag=>tag.trim()).filter(Boolean),expectedRowVersion:editVersion},props.token),'经验已发布，供后续项目复用。')}
function openAdoption(item:QualityExperience){open('adoption');adoptionDraft.value={experienceId:item.id,projectIds:[],owner:'',dueOn:''}}
function useRecommended(){const item=data.value?.catalog.experiences.find(row=>row.id===adoptionDraft.value.experienceId);adoptionDraft.value.projectIds=[...((item?.recommendedProjectIds??[]).filter(id=>data.value?.projects.some(project=>project.id===id&&project.rootProjectId===id)))]}
async function saveAdoption(){const item=adoptionDraft.value;if(!item.projectIds.length||!item.owner||!item.dueOn){dialogError.value='请选择目标项目、落实人和完成日期。';return}await perform(()=>assignQualityAdoption({...item,expectedRowVersion:editVersion},props.token),'项目经验采用任务已建立。')}
async function saveSettings(){if(!data.value)return;await perform(()=>saveQualitySettings({...settingsDraft.value,expectedRowVersion:data.value!.catalog.rowVersion},props.token),'高频识别设置已保存。')}
function inspect(row:QualityIssueRow){focusedIssue.value=row;open('issue',row.issue.id)}
</script>

<template>
  <section class="quality-review" aria-label="公司问题与改善">
    <p v-if="error" role="alert" class="quality-review__error">{{ error }}</p><p v-if="message" role="status" class="quality-review__success">{{ message }}</p>
    <nav v-if="!themesOnly" class="quality-review__tabs wh-tabs pdm-tabs" role="tablist" aria-label="公司问题视图"><button v-if="caps.canViewDetails" role="tab" :aria-selected="tab==='issues'" @click="tab='issues'">问题总表</button><button role="tab" :aria-selected="tab==='themes'" @click="tab='themes'">共性问题</button><button role="tab" :aria-selected="tab==='improvements'" @click="tab='improvements'">改善事项</button><button role="tab" :aria-selected="tab==='experience'" @click="tab='experience'">经验复用</button><button v-if="caps.canViewDetails" role="tab" :aria-selected="tab==='summaries'" @click="tab='summaries'">项目总结</button><button v-if="caps.canManageSettings" role="tab" :aria-selected="tab==='settings'" @click="tab='settings'">统计设置</button></nav>
    <div v-if="!showIssueFilters && !data" class="quality-review__actions"><button type="button" :disabled="loading||busy" @click="load">刷新</button></div>
    <p v-if="loading" role="status">正在读取公司问题与改善…</p>
    <template v-if="data && (!loading || showIssueFilters)">
      <div v-if="!themesOnly" class="quality-review__stats"><article class="pdm-stat-card"><span>共性问题</span><strong>{{ data.metrics.length }}<small>类</small></strong><em class="pdm-stat-card__detail">{{ data.windowFrom }} 至 {{ data.windowTo }}</em></article><article class="pdm-stat-card" :class="{'is-warning':candidates.length>0}"><span>建议改善</span><strong>{{ candidates.length }}<small>项</small></strong><em class="pdm-stat-card__detail">高频或重大问题，由授权人员确认</em></article><article class="pdm-stat-card"><span>持续改善</span><strong>{{ pendingImprovements.length }}<small>项</small></strong><em class="pdm-stat-card__detail">实施、观察及验证中的事项</em></article></div>
      <div v-if="!showIssueFilters && tab !== 'themes' && tab !== 'improvements'" class="quality-review__actions">
        <button type="button" :disabled="loading || busy" @click="load">刷新</button>
      </div>
      <template v-if="showIssueFilters">
        <div class="quality-review__filters"><label>项目<select v-model="projectFilter"><option value="">全部授权项目</option><option v-for="item in data.projects" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select></label><label>问题类型<select v-model="domainFilter"><option value="">全部类型</option><option>未分类</option><option>质量</option><option>设计</option><option>采购</option><option>生产</option><option>进度</option><option>成本</option><option>其他</option></select></label><label>公司共性问题<select v-model="themeFilter"><option value="">全部主题</option><option value="__unassigned">待归类</option><option v-for="item in data.catalog.themes" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>状态<select v-model="stateFilter"><option value="">全部状态</option><option>未完成</option><option>已完成</option><option>已作废</option></select></label><label>关键词<input v-model="query" placeholder="问题/项目" title="搜索问题、项目或分类"></label>
          <button class="quality-review__filter-refresh" type="button" :disabled="loading || busy" @click="load">刷新</button>
        </div>
        <div class="quality-review__scroll"><table><thead><tr><th>项目</th><th>编号</th><th>问题</th><th>问题类型</th><th>公司共性问题</th><th>实际发生</th><th>严重程度</th><th>状态</th><th>负责人</th><th>操作</th></tr></thead><tbody><tr v-for="row in issues" :key="row.issue.id"><td>{{ row.projectCode }}</td><td>{{ row.issue.number }}</td><td>{{ row.issue.description }}</td><td>{{ row.profile?.domain||'待分类' }}</td><td>{{ row.profile?.themeId?themeName(row.profile.themeId):'未归类' }}</td><td>{{ row.profile?.occurredOn||'日期待核对' }}</td><td>{{ row.profile?.severity||'未评定' }}</td><td>{{ row.issue.status }}</td><td><PersonName :name="row.ownerName||'姓名待补充'" /></td><td><button v-if="row.canOpenProject" @click="inspect(row)">闭环资料</button><button v-if="row.canOpenProject" @click="emit('openIssue',row.issue.relatedProjectId||row.issue.projectId,row.issue.id)">原问题</button><span v-else>项目明细未授权</span></td></tr><tr v-if="!issues.length"><td colspan="10" class="quality-review__empty">没有符合条件的问题。</td></tr></tbody></table></div>
      </template>
      <template v-if="tab==='themes'">
        <header class="quality-review__toolbar"><p class="quality-review__hint">将各项目同类问题归入统一主题，汇总发生次数并推动改善。日常填报可以先不归类，由授权人员在公司复盘时补充。</p><div class="quality-review__actions"><button type="button" :disabled="loading || busy" @click="load">刷新</button><button v-if="caps.canManageThemes" @click="editTheme()">新增主题</button></div></header>
        <div v-if="!themesOnly" class="quality-review__scroll"><table><thead><tr><th>共性问题</th><th>事件次数</th><th>涉及项目</th><th>重大问题</th><th>日期未知</th><th>改善建议</th><th>操作</th></tr></thead><tbody><tr v-for="item in data.metrics" :key="item.themeId"><td>{{ item.name }}</td><td>{{ item.eventCount }}</td><td>{{ item.projectCount }}</td><td>{{ item.majorCount }}</td><td>{{ item.unknownDateCount }}</td><td>{{ item.activeImprovementId?'改善进行中':item.isCandidate?'建议评估改善':'持续观察' }}</td><td><button v-if="caps.canViewDetails" @click="themeFilter=item.themeId;tab='issues'">关联事件</button><button v-if="caps.canManageThemes" :disabled="busy" @click="editTheme(data.catalog.themes.find(theme=>theme.id===item.themeId))">维护</button><button v-if="caps.canManageThemes" :disabled="busy" @click="removeTheme(item.themeId,item.name)">删除</button><button v-if="item.activeImprovementId||caps.canManageImprovements" @click="newFromTheme(item.themeId)">{{ item.activeImprovementId?'查看改善':'发起改善' }}</button></td></tr><tr v-if="!data.metrics.length"><td colspan="7" class="quality-review__empty">暂无共性主题，请先归类项目问题。</td></tr></tbody></table></div>
        <p v-if="themesOnly&&!data.catalog.themes.length" class="quality-review__empty">暂无共性问题，可由授权人员新增主题。</p><details v-if="data.catalog.themes.length" :open="themesOnly"><summary>主题目录（含未发生及停用主题）</summary><div class="quality-review__scroll"><table><thead><tr><th>主题</th><th>说明</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in data.catalog.themes" :key="item.id"><td>{{ item.name }}</td><td>{{ item.description||'—' }}</td><td>{{ item.isActive?'启用':'停用' }}</td><td><button v-if="caps.canManageThemes" :disabled="busy" @click="editTheme(item)">维护</button><button v-if="caps.canManageThemes" :disabled="busy" @click="removeTheme(item.id,item.name)">删除</button></td></tr></tbody></table></div></details>
      </template>
      <template v-if="tab==='improvements'">
        <header class="quality-review__toolbar"><div class="quality-review__filters"><label>共性主题<select v-model="themeFilter"><option value="">全部主题</option><option v-for="item in data.catalog.themes" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></div><div class="quality-review__actions"><button type="button" :disabled="loading || busy" @click="load">刷新</button><button v-if="caps.canManageImprovements" @click="editImprovement()">新增改善</button></div></header>
        <div class="quality-review__scroll"><table><thead><tr><th>改善事项</th><th>主题</th><th>负责人</th><th>状态</th><th>目标日期</th><th>观察样本</th><th>操作</th></tr></thead><tbody><tr v-for="item in displayedImprovements" :key="item.id" :aria-selected="selectedId===item.id"><td>{{ item.title }}</td><td>{{ themeName(item.themeId) }}</td><td><PersonName :name="qualityName(people,item.owner)" /></td><td>{{ item.state }}</td><td>{{ item.dueOn }}</td><td>{{ item.observations.length }} / {{ item.minimumSamples }}</td><td><button @click="selectedId=item.id">详情</button></td></tr><tr v-if="!displayedImprovements.length"><td colspan="7" class="quality-review__empty">暂无改善事项。</td></tr></tbody></table></div>
        <article v-if="selected" class="quality-review__card"><header class="quality-review__toolbar"><h3>{{ selected.title }}</h3><div class="quality-review__actions">
          <button v-if="selected.state==='草稿'&&caps.canManageImprovements||selected.state==='实施中'&&caps.canExecuteImprovements" :disabled="busy" @click="editImprovement(selected)">{{ selected.state==='草稿'?'编辑':'更新措施' }}</button><button v-if="selected.state==='草稿'&&caps.canApproveImprovements" :disabled="busy" @click="transition('approve','批准实施')">批准实施</button><button v-if="selected.state==='实施中'&&caps.canExecuteImprovements" :disabled="busy" @click="transition('observe','开始观察')">开始观察</button><template v-if="selected.state==='观察中'&&caps.canExecuteImprovements"><button :disabled="busy" @click="openObservation">记录样本</button><button :disabled="busy" @click="transition('submit-verification','提交验证')">提交验证</button></template><button v-if="selected.state==='待验证'&&caps.canVerifyImprovements" :disabled="busy" @click="transition('verify','独立验证')">独立验证</button><button v-if="selected.state==='已验证'&&caps.canCloseImprovements" :disabled="busy" @click="transition('close','关闭改善')">关闭改善</button><button v-if="!['草稿','已撤销'].includes(selected.state)&&caps.canManageImprovements" :disabled="busy" @click="transition('reopen','重开修订')">重开修订</button><button v-if="['观察中','待验证','已验证'].includes(selected.state)&&caps.canExecuteImprovements" :disabled="busy" @click="transition('return-to-implementation','退回实施')">退回实施</button><button v-if="['草稿','实施中'].includes(selected.state)&&caps.canManageImprovements" :disabled="busy" @click="transition('cancel','取消改善')">取消改善</button><button v-if="selected.state==='已关闭'&&caps.canPublishExperience" :disabled="busy" @click="openExperience()">发布经验</button>
        </div></header><div class="quality-review__detail"><p><strong>共同原因</strong>{{ selected.rootCause||'待补充' }}</p><p><strong>改善目标</strong>{{ selected.goal||'待补充' }}</p><p><strong>预先确定的验证标准</strong>至少 {{ selected.minimumSamples }} 个主项目样本，观察 {{ selected.observationDays }} 天，最多 {{ selected.maximumFailures }} 次失败。</p><p><strong>观察开始</strong>{{ qualityDate(selected.observationStartedAt) }}</p></div>
          <h3>措施及实施证据</h3><div class="quality-review__scroll"><table><thead><tr><th>措施</th><th>负责人</th><th>期限</th><th>完成</th><th>实施证据</th></tr></thead><tbody><tr v-for="action in selected.actions" :key="action.id"><td>{{ action.title }}</td><td><PersonName :name="qualityName(people,action.owner)" /></td><td>{{ action.dueOn }}</td><td>{{ action.completed?'已完成':'未完成' }}</td><td>{{ action.evidence||'待补充' }}</td></tr><tr v-if="!selected.actions.length"><td colspan="5">暂无措施</td></tr></tbody></table></div>
          <h3>效果观察</h3><p class="quality-review__hint">没有适用样本时保持待验证；零样本不代表改善有效。独立验证人与创建人、负责人、措施执行人分离。</p><div class="quality-review__scroll"><table><thead><tr><th>样本项目</th><th>实施日期</th><th>观察日期</th><th>结果</th><th>证据</th><th>记录人</th></tr></thead><tbody><tr v-for="(item,index) in selected.observations" :key="index"><td>{{ projectName(item.projectId) }}</td><td>{{ item.appliedOn }}</td><td>{{ item.observedOn }}</td><td>{{ item.passed?'通过':'失败' }}</td><td>{{ item.evidence }}</td><td><PersonName :name="qualityName(people,item.recordedBy)" /></td></tr><tr v-if="!selected.observations.length"><td colspan="6">尚未登记适用样本</td></tr></tbody></table></div>
          <details v-if="selected.previousCycles?.length"><summary>历史改善轮次（{{ selected.previousCycles.length }}）</summary><article v-for="(cycle,index) in selected.previousCycles" :key="index" class="quality-review__card"><h4>第 {{ index+1 }} 轮 · {{ qualityDate(cycle.endedAt) }}</h4><p>{{ cycle.reason }}</p><p>原状态：{{ cycle.state }} · 最少 {{ cycle.minimumSamples }} 个样本 / {{ cycle.observationDays }} 天 / 最多 {{ cycle.maximumFailures }} 次失败</p><div class="quality-review__scroll"><table><thead><tr><th>原措施</th><th>负责人</th><th>状态</th><th>证据</th></tr></thead><tbody><tr v-for="action in cycle.actions" :key="action.id"><td>{{ action.title }}</td><td><PersonName :name="qualityName(people,action.owner)" /></td><td>{{ action.completed?'已完成':'未完成' }}</td><td>{{ action.evidence||'—' }}</td></tr></tbody></table><table><thead><tr><th>原样本项目</th><th>观察日期</th><th>结果</th><th>证据</th></tr></thead><tbody><tr v-for="(sample,number) in cycle.observations" :key="number"><td>{{ projectName(sample.projectId) }}</td><td>{{ sample.observedOn }}</td><td>{{ sample.passed?'通过':'失败' }}</td><td>{{ sample.evidence }}</td></tr></tbody></table></div></article></details><details><summary>过程记录（{{ selected.history.length }}）</summary><ol class="quality-review__history"><li v-for="(item,index) in selected.history" :key="index">{{ qualityDate(item.at) }} · <PersonName :name="item.actorName||'姓名待补充'" /> · {{ qualityEventLabel(item.action) }}<p>{{ item.note }}</p></li></ol></details>
        </article>
      </template>
      <template v-if="tab==='experience'"><p class="quality-review__hint">经验证有效的改善可发布为经验。项目记录采用证据或不适用原因，历史版本继续保留。</p><article v-for="item in data.catalog.experiences" :key="item.id" class="quality-review__card"><header class="quality-review__toolbar"><h3>{{ item.title }} · R{{ item.revision }}</h3><div class="quality-review__actions"><button v-if="caps.canPublishExperience" @click="openExperience(item)">修订发布</button><button v-if="caps.canPublishExperience" @click="openAdoption(item)">安排采用</button></div></header><div class="quality-review__detail"><p><strong>适用范围</strong>{{ item.applicability }}</p><p><strong>经验内容</strong>{{ item.content }}</p></div><p class="quality-review__hint">发布人：<PersonName :name="qualityName(people,item.publishedBy)" /> · {{ qualityDate(item.publishedAt) }}</p><div class="quality-review__scroll"><table><thead><tr><th>采用项目</th><th>落实人</th><th>期限</th><th>状态</th><th>证据 / 不适用原因</th></tr></thead><tbody><tr v-for="adoption in data.catalog.adoptions.filter(row=>row.experienceId===item.id)" :key="adoption.id"><td>{{ projectName(adoption.projectId) }}</td><td><PersonName :name="qualityName(people,adoption.owner)" /></td><td>{{ adoption.dueOn }}</td><td>{{ adoption.state }}</td><td>{{ adoption.evidence||'待检查' }}</td></tr><tr v-if="!data.catalog.adoptions.some(row=>row.experienceId===item.id)"><td colspan="5">尚未安排项目采用</td></tr></tbody></table></div></article><p v-if="!data.catalog.experiences.length" class="quality-review__empty">暂无已发布经验。改善完成效果验证并关闭后，可发布经验。</p></template>
      <template v-if="tab==='summaries'&&caps.canViewDetails"><div class="quality-review__scroll"><table><thead><tr><th>项目</th><th>总结</th><th>类型</th><th>版本</th><th>状态</th><th>发布日期</th><th>经验教训</th><th>后续计划</th></tr></thead><tbody><tr v-for="item in data.catalog.summaries" :key="item.id"><td>{{ projectName(item.projectId) }}</td><td>{{ item.title }}</td><td>{{ item.kind }}</td><td>R{{ item.revision }}</td><td>{{ item.state }}</td><td>{{ qualityDate(item.publishedAt) }}</td><td>{{ item.lessons||'—' }}</td><td>{{ item.remainingPlan||'—' }}</td></tr><tr v-if="!data.catalog.summaries.length"><td colspan="8" class="quality-review__empty">暂无可见项目总结。</td></tr></tbody></table></div></template>
      <form v-if="tab==='settings'&&caps.canManageSettings" class="quality-review__card" @submit.prevent="saveSettings"><h3>高频问题识别</h3><fieldset :disabled="busy" class="quality-review__form quality-review__settings-fields"><label>统计窗口（天）<input v-model.number="settingsDraft.windowDays" type="number" step="1" min="1" max="3650" required></label><label>事件次数阈值<input v-model.number="settingsDraft.eventThreshold" type="number" step="1" min="1" max="10000" required></label><label>涉及项目阈值<input v-model.number="settingsDraft.projectThreshold" type="number" step="1" min="1" max="10000" required></label></fieldset><p class="quality-review__hint">达到事件次数或项目数任一阈值，或出现重大问题时提示改善候选。已有进行中的改善继续关联，不自动重复建立改善事项。</p><div class="quality-review__actions"><button type="submit" :disabled="busy" class="pdm-primary-action">保存设置</button></div></form>
    </template>

    <el-dialog :model-value="!!dialog" :title="dialogTitle" width="min(1000px, 94vw)" append-to-body :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" @update:model-value="(value:boolean)=>{if(!value&&!busy)dialog=''}">
      <section class="quality-review" style="height:auto"><p v-if="dialogError" role="alert" class="quality-review__error">{{ dialogError }}</p>
        <QualityIssuePanel :show-company-review-entry="showCompanyReviewEntry" :company-review-revision="companyReviewRevision" @open-company-review="emit('openCompanyReview')" v-if="dialog==='issue'&&focusedIssue" :token="token" :project-id="focusedIssue.issue.relatedProjectId||focusedIssue.issue.projectId" :issue-id="focusedIssue.issue.id" @updated="load();emit('updated')" />
        <form v-if="dialog==='theme'" @submit.prevent="saveTheme"><fieldset class="quality-review__form" :disabled="busy"><label class="quality-review__wide">主题名称<input v-model="themeDraft.name" maxlength="200" required></label><label class="quality-review__wide">定义及归类边界<textarea v-model="themeDraft.description" maxlength="4000" /></label><label>状态<select v-model="themeDraft.isActive"><option :value="true">启用</option><option :value="false">停用</option></select></label></fieldset><div class="quality-review__actions"><button type="submit" :disabled="busy" class="pdm-primary-action">保存主题</button></div></form>
        <form v-if="dialog==='improvement'" @submit.prevent="saveImprovement"><fieldset class="quality-review__form" :disabled="busy||!canEditDefinition"><label>主题<select v-model="improvementDraft.themeId" required><option value="">请选择</option><option v-for="item in data?.catalog.themes.filter(row=>row.isActive||row.id===improvementDraft.themeId)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>改善标题<input v-model="improvementDraft.title" maxlength="200" required></label><label>负责人<UserSelect v-model="improvementDraft.owner" :disabled="busy||!canEditDefinition" required><option value="">请选择姓名</option><option v-for="person in people" :key="person.username" :value="person.username">{{ person.displayName||'姓名待补充' }}</option></UserSelect></label><label>完成日期<input v-model="improvementDraft.dueOn" type="date" required></label><label class="quality-review__wide">共同原因<textarea v-model="improvementDraft.rootCause" maxlength="4000" /></label><label class="quality-review__wide">目标及适用样本定义<textarea v-model="improvementDraft.goal" maxlength="4000" /></label><label>最少观察项目数<input v-model.number="improvementDraft.minimumSamples" type="number" min="1" max="10000" step="1" required></label><label>最少观察天数<input v-model.number="improvementDraft.observationDays" type="number" min="1" max="3650" step="1" required></label><label>允许失败次数<input v-model.number="improvementDraft.maximumFailures" type="number" min="0" max="10000" step="1" required></label></fieldset>
          <p class="quality-review__hint">验证标准批准后锁定。措施完成须有实施证据，效果观察另行记录。</p><header class="quality-review__toolbar"><h3>改善措施</h3><button type="button" :disabled="busy||!canEditDefinition" @click="addAction">新增措施</button></header>
          <fieldset :disabled="busy" class="quality-review__form"><article v-for="(action,index) in improvementDraft.actions" :key="action.id" class="quality-review__card quality-review__wide"><label>措施内容<input v-model="action.title" :disabled="!canEditDefinition" maxlength="500" required></label><div class="quality-review__form"><label>负责人<UserSelect v-model="action.owner" :disabled="!canEditDefinition" required><option value="">请选择姓名</option><option v-for="person in people" :key="person.username" :value="person.username">{{ person.displayName||'姓名待补充' }}</option></UserSelect></label><label>完成日期<input v-model="action.dueOn" :disabled="!canEditDefinition" type="date" required></label></div><label>实施证据<textarea v-model="action.evidence" maxlength="4000" /></label><div class="quality-review__toolbar"><label><input v-model="action.completed" :disabled="canEditDefinition" type="checkbox"> 已完成实施</label><button type="button" :disabled="!canEditDefinition" @click="improvementDraft.actions.splice(index,1)">移除措施</button></div></article></fieldset><div class="quality-review__actions"><button type="submit" :disabled="busy" class="pdm-primary-action">保存改善</button></div>
        </form>
        <form v-if="dialog==='observation'" @submit.prevent="saveObservation"><fieldset class="quality-review__form" :disabled="busy"><label>样本项目<select v-model="observationDraft.projectId" required><option value="">请选择</option><option v-for="item in data?.projects.filter(row=>row.id===row.rootProjectId)" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select></label><label>观察结果<select v-model="observationDraft.passed"><option :value="true">通过</option><option :value="false">失败</option></select></label><label>实施日期<input v-model="observationDraft.appliedOn" type="date" required></label><label>观察日期<input v-model="observationDraft.observedOn" type="date" required></label><label class="quality-review__wide">观察结果与证据<textarea v-model="observationDraft.evidence" maxlength="4000" required /></label></fieldset><div class="quality-review__actions"><button type="submit" :disabled="busy" class="pdm-primary-action">保存样本</button></div></form>
        <form v-if="dialog==='experience'" @submit.prevent="saveExperience"><fieldset class="quality-review__form" :disabled="busy"><label>来源改善<select v-model="experienceDraft.improvementId" required><option value="">请选择已关闭改善</option><option v-for="item in data?.catalog.improvements.filter(row=>row.state==='已关闭')" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>经验标题<input v-model="experienceDraft.title" maxlength="200" required></label><label class="quality-review__wide">适用项目、工况及边界<textarea v-model="experienceDraft.applicability" maxlength="4000" required /></label><label class="quality-review__wide">项目适用标签<input v-model="experienceTags" maxlength="1200" placeholder="用顿号分隔项目类型、设备型号或名称关键词"></label><label class="quality-review__wide">可复用措施、标准和检查方法<textarea v-model="experienceDraft.content" maxlength="10000" required /></label></fieldset><div class="quality-review__actions"><button type="submit" :disabled="busy" class="pdm-primary-action">发布经验</button></div></form>
        <form v-if="dialog==='adoption'" @submit.prevent="saveAdoption"><fieldset :disabled="busy" class="quality-review__form"><div class="quality-review__wide"><div class="quality-review__toolbar"><strong>目标主项目</strong><button type="button" @click="useRecommended">采用推荐</button></div><p class="quality-review__hint">推荐按经验标签匹配项目；选择后仍需确认安排。</p><div class="quality-review__checklist"><label v-for="item in data?.projects.filter(project=>project.rootProjectId===project.id)" :key="item.id"><input v-model="adoptionDraft.projectIds" :value="item.id" type="checkbox">{{ item.code }} · {{ item.name }}</label></div></div><label>落实人<UserSelect v-model="adoptionDraft.owner" :disabled="busy" required><option value="">请选择姓名</option><option v-for="person in people" :key="person.username" :value="person.username">{{ person.displayName||'姓名待补充' }}</option></UserSelect></label><label>完成日期<input v-model="adoptionDraft.dueOn" type="date" required></label></fieldset><div class="quality-review__actions"><button type="submit" :disabled="busy" class="pdm-primary-action">安排采用</button></div></form>
      </section>
    </el-dialog>
  </section>
</template>
